import { PickD3Scale } from '@visx/scale';
import { ReactElement } from 'react';

import { ConvertibleUnit, FormatOptions, Unit } from '@dynatrace-sdk/units';

import { HistogramAnnotationsConfigProps } from './histogram-annotations.js';
import { StylingProps } from '../../../core/types/styling-props.js';
import { TruncationMode } from '../../../typography/TextEllipsis.js';
import { ChartUnit } from '../../core/types/chart-unit.js';
import {
  CustomColorPalette,
  ColorToken,
  ColorPalette,
} from '../../core/types/color-palette.js';
import { Formatter } from '../../core/types/formatter.js';
import { ChartInteractionsConfig } from '../../core/types/interactions.js';
import { LegendProps } from '../../core/types/legend.js';
import { AxisScaleType } from '../../core/types/scales.js';
import { ChartToolbarConfig } from '../../core/types/toolbar.js';
import { WithId } from '../../core/types/with-id.js';
import { HistogramThresholdProps } from '../slots/Threshold.js';

export interface HistogramBin {
  /**
   * The start of the bin or bucket
   */
  from: number;
  /**
   * The end of the bin or bucket
   */
  to: number;
  /**
   * The value, better known as "frequency"
   */
  value: number;
}

export interface HistogramSeries {
  /**
   * The histogram series data to be graphed by the component
   */
  bins: HistogramBin[];
  /**
   * The name for the histogram series
   */
  name: string;
  /**
   * Unit token for the values in the y-axis of the histogram series
   */
  unit?: ChartUnit;
}

export interface SeriesMetadata {
  id: string;
  color: ColorToken;
  scaleIndex: number;
}

export interface BinMetadata extends HistogramBin {
  seriesId: string;
  color: ColorToken;
  unit: ChartUnit;
  seriesName: string;
  cumulativeValue?: number;
}

export type WeakMapSeries = WeakMap<object, SeriesMetadata>;
export type WeakMapBins = WeakMap<object, BinMetadata>;

export interface HistogramChartProps extends StylingProps {
  /**
   * Data object for the histogram chart
   */
  data: HistogramSeries[];
  /**
   * Chart height. When a number is specified, it's treated as pixels,
   * otherwise a valid height string is expected.
   * @defaultValue 300px
   */
  height?: number | string;
  /**
   * Actions to be shown in the legend and tooltip actions
   */
  seriesActions?: (series: HistogramSeries, bin: HistogramBin) => ReactElement;
  /**
   * Truncation mode to use (start, middle, end)
   * Applied to all the parts that truncate text.
   * @defaultValue 'middle'
   */
  truncationMode?: TruncationMode;
  /**
   * Color palette to be used for the bar category.
   * @defaultValue "categorical"
   */
  colorPalette?: ColorPalette | CustomColorPalette;
  /** Show the loading indicator when truthy.
   * @defaultValue false
   */
  loading?: boolean;
}

export interface HistogramDataPoint {
  /**
   * The value in X axis
   */
  x: number;
  /**
   * The value in Y axis
   */
  y: number;
}

export interface ContinuousSeries {
  /**
   * The continuous series data to be graphed by the component
   */
  dataPoints: HistogramDataPoint[];
  /**
   * The name or names in case of multiple dimensions for the continuous series
   */
  name: string;
  /**
   * Unit token for the values in the y-axis of the histogram chart
   */
  unit?: ChartUnit;
}

export interface HistogramChartConfigProperties {
  /**
   * Chart toolbar configuration
   */
  toolbar?: HistogramChartToolbarProps;
  /**
   * Chart interactions configuration
   * */
  interactions?: ChartInteractionsConfig;
  /**
   * Chart legend properties
   */
  legend?: HistogramChartLegendProps;
  /**
   * Chart X axis properties
   */
  xAxis?: HistogramChartXAxisProps;
  /**
   *  Chart Y axis properties
   */
  yAxis?: HistogramChartYAxisProps[];
  /**
   * Chart tooltip properties
   */
  tooltip?: HistogramChartTooltipProps;
  /**
   * Color palette
   */
  colorPalette?: ColorPalette | CustomColorPalette;
  /**
   * The trunctation mode to use (start, middle, center)
   * Applied to all the parts that truncate text.
   * @defaultValue 'middle'
   */
  truncationMode?: TruncationMode;
  /**
   * Chart thresholds configuration
   */
  thresholds?: HistogramThresholdProps[];
}

export const histogramTooltipVariantOptions = [
  'single',
  'shared',
  'grouped',
] as const;
export type HistogramTooltipVariant =
  (typeof histogramTooltipVariantOptions)[number];

/** Props for the HistogramChart.Tooltip slot component */
export interface HistogramChartTooltipProps {
  /**
   * Whether the tooltip should contain bins from
   * all series or just the closest one.
   */
  variant?: HistogramTooltipVariant;
}

export interface HistogramChartXAxisProps {
  /**
   * The max value configuration to display in the axis
   * @defaultValue 'auto'
   */
  max?: number | 'auto' | 'data-max';
  /**
   * The min value configuration to display in the axis
   * @defaultValue 'auto'
   */
  min?: number | 'auto' | 'data-min';
  /**
   * The title used for the axis
   */
  label?: string;
  /**
   * The scale to be used
   */
  scale?: AxisScaleType;
  /**
   * Formatter to be applied for each tick of the axis
   */
  formatter?: Formatter | FormatOptions<Unit, ConvertibleUnit>;
  /**
   * The unit for the axis
   */
  unit?: ChartUnit;
}

export interface HistogramChartYAxisProps {
  /**
   * The max value configuration to display in the axis
   * @defaultValue 'auto'
   */
  max?: number | 'auto' | 'data-max';
  /**
   * The min value configuration to display in the axis
   * @defaultValue 'auto'
   */
  min?: number | 'auto' | 'data-min';
  /**
   * The title used for the axis
   */
  label?: string;
  /**
   * The scale to be used
   */
  scale?: AxisScaleType;
  /**
   * Formatter to be applied for each tick of the axis
   */
  formatter?: Formatter | FormatOptions<Unit, ConvertibleUnit>;
  /**
   * The position of the y axis relative to
   * the histogram chart
   * @defaultValue 'left'
   */
  position?: 'left' | 'right';
}

export type HistogramThresholdConfig = HistogramThresholdProps;

export interface HistogramThresholdsConfig {
  leftThreshold?: WithId<HistogramThresholdConfig>[];
  rightThreshold?: WithId<HistogramThresholdConfig>[];
}

export interface HistogramChartConfiguration {
  /**
   * Color palette
   */
  colorPalette: ColorPalette | CustomColorPalette;
  /**
   * Defines tooltip configuration
   * */
  tooltip: HistogramChartTooltipConfig;
  /**
   * Chart toolbar configuration
   */
  toolbar?: HistogramChartToolbarConfig;
  /**
   * Chart legend configuration
   */
  legend: HistogramChartLegendConfig;
  /**
   * Chart X axis configuration
   */
  xAxis: HistogramChartXAxisConfig;
  /**
   * Chart Y axis configuration
   */
  yAxis: HistogramChartYAxisConfig;
  /**
   * Truncation mode applied when text overflows
   */
  truncationMode: TruncationMode;
  /**
   * Annotations configuration
   */
  annotations?: HistogramAnnotationsConfigProps;
  /**
   * Chart Interactions configuration
   */
  interactions?: ChartInteractionsConfig;
  /**
   * Chart thresholds configuration
   */
  thresholds?: HistogramThresholdsConfig;
}

/**
 * @internal
 */
export type HistogramChartTooltipConfig = Required<HistogramChartTooltipProps>;

export type AxesUnits = [ChartUnit, ChartUnit];

export type HistogramChartLegendProps = LegendProps;

/**
 *  Props for the ChartToolbar implementation in HistogramChart
 */
export interface HistogramChartToolbarProps extends ChartToolbarConfig {
  /** Toggles the toolbar display */
  enabled?: boolean;
}

/**
 * @internal
 */
export type HistogramChartToolbarConfig = HistogramChartToolbarProps;

/**
 * @internal
 */
export type HistogramChartLegendConfig = HistogramChartLegendProps;

/**
 * @internal
 */
export interface HistogramChartXAxisConfig extends HistogramChartXAxisProps {
  scale: AxisScaleType;
}

/**
 * @internal
 */
export interface HistogramChartYAxisConfig {
  left?: HistogramChartYAxisProps;
  right?: HistogramChartYAxisProps;
}

export type HistogramChartConfigProps = {
  toolbar?: HistogramChartToolbarProps;
  legend?: HistogramChartLegendProps;
  xAxis?: HistogramChartXAxisProps;
  yAxis?: HistogramChartYAxisProps;
  tooltip?: HistogramChartTooltipProps;
  colorPalette?: ColorPalette | CustomColorPalette;
  truncationMode?: TruncationMode;
};

export interface HistogramChartSlots {
  /**
   * Chart Toolbar slot
   */
  toolbar: HistogramChartToolbarProps;
  /**
   * Chart legend slot
   */
  legend: HistogramChartLegendProps;
  /**
   * Chart X axis slot
   */
  xAxis?: HistogramChartXAxisProps;
  /**
   * Chart Y axis slot
   */
  yAxis: HistogramChartYAxisProps[];
  /**
   * Chart tooltip slot
   */
  tooltip: HistogramChartTooltipProps;
  /**
   * Chart Annotations slot
   */
  annotations?: HistogramAnnotationsConfigProps;
  /**
   * Chart Interactions slot
   */
  interactions?: ChartInteractionsConfig;
  /**
   * Chart thresholds slot
   */
  thresholds: HistogramThresholdProps[];
}

export type XScale = PickD3Scale<AxisScaleType, number>;
export type YScale = PickD3Scale<AxisScaleType, number>;

/** API config for a chart zoom interaction */
export interface ChartZoomConfig {
  /** Enables a specific zoom interaction on the chart. */
  enabled?: boolean;
}
